'use strict';
const $=id=>document.getElementById(id),base=document.body.dataset.base||'./',detailId=document.body.dataset.paper||null,R=window.DigestReader;
const params=new URLSearchParams(location.search);let lang=params.get('lang');if(!['zh','en'].includes(lang)){try{lang=localStorage.getItem('digest-language');}catch{}if(!['zh','en'].includes(lang))lang='zh';}
let data,catalog,topics,pool,revisions,statusSnapshot={},liveRuns=null,view=params.get('view')||'library',selected=params.get('issue')||'',topicId=params.get('topic')||'',query=params.get('q')||'',priority=params.get('priority')||'',reading=params.get('reading')||'';
const filters={},tags=new Set(params.getAll('tag'));
const el=(tag,cls,text)=>{const n=document.createElement(tag);if(cls)n.className=cls;if(text!==undefined)n.textContent=text;return n;};
const t=key=>window.DIGEST_I18N[lang][key]||key,term=value=>lang==='en'?(window.DIGEST_TERMS[value]||value):value;
function link(text,url){const a=el('a','',text);a.href=url;return a;}function external(text,url){const a=link(text,url);a.target='_blank';a.rel='noopener noreferrer';return a;}
