function safeURL(url){try{return new URL(url).protocol==='https:';}catch{return false;}}
function route(values={}){const p=new URLSearchParams({lang,...values});return base+'?'+p;}
function paperHref(id,version){return base+'papers/'+encodeURIComponent(id)+'/?lang='+lang+(version?'&version='+version:'');}
function updateURL(){const p=new URLSearchParams({lang});if(view!=='library')p.set('view',view);if(selected)p.set('issue',selected);if(topicId)p.set('topic',topicId);if(query)p.set('q',query);if(priority)p.set('priority',priority);if(reading)p.set('reading',reading);for(const[k,v]of Object.entries(filters))if(v)p.set(k,v);for(const tag of tags)p.append('tag',tag);if(detailId&&params.has('version'))p.set('version',params.get('version'));history.replaceState(null,'',location.pathname+'?'+p);}
function option(select,value,label){const o=el('option','',label);o.value=value;select.append(o);}
function download(name,content,type='text/plain'){const url=URL.createObjectURL(new Blob([content],{type})),a=link('',url);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function exports(papers){const box=el('div','paper-actions');box.append(button(t('exportRIS'),()=>download('plant-epigenomics.ris',R.ris(papers),'application/x-research-info-systems')),button(t('exportBib'),()=>download('plant-epigenomics.bib',R.bibtex(papers),'application/x-bibtex')));return box;}
function matchesTopic(p,topic){return Object.entries(topic.match).some(([key,values])=>values.some(v=>(p.classification[key]||[]).includes(v)));}
function filteredPapers(){let rows=selected?(data.issues.find(i=>i.date===selected)?.papers||[]):catalog.papers;const topic=topics.find(x=>x.id===topicId);return rows.filter(p=>{const r=R.get(p.id);return(!priority||p.priority===priority)&&(!topic||matchesTopic(p,topic))&&(view!=='personal'||r.star||r.state||r.note)&&(!reading||(reading==='star'?r.star:r.state===reading))&&Object.entries(filters).every(([k,v])=>!v||(p.classification[k]||[]).includes(v))&&[...tags].every(tag=>{const[k,v]=tag.split(':');return(p.classification[k]||[]).includes(v);})&&(!query||[p.title,p.heading,p.journal,...(p.tags||[]),...p.sections.map(s=>s.text),p.translations?.en?.heading,...(p.translations?.en?.sections||[]).map(s=>s.text),...Object.values(p.classification).flat().flatMap(v=>[v,window.DIGEST_TERMS[v]||v])].join(' ').toLowerCase().includes(query.toLowerCase()));});}
function renderReader(p){const box=el('details','reader'),summary=el('summary','',t('seeNotes'));box.append(summary);const controls=el('div','reader-controls'),state=el('select');state.setAttribute('aria-label',t('readState'));for(const v of ['','todo','read'])option(state,v,t(v||'unread'));state.value=R.get(p.id).state;const status=el('small','',R.isPersistent()?t('saved'):t('saveFailed'));state.onchange=()=>{status.textContent=t(R.set(p.id,{state:state.value})?'saved':'saveFailed');};const star=button(t(R.get(p.id).star?'starred':'star'),()=>{const value=!R.get(p.id).star;status.textContent=t(R.set(p.id,{star:value})?'saved':'saveFailed');star.textContent=t(value?'starred':'star');star.setAttribute('aria-pressed',String(value));});star.setAttribute('aria-pressed',String(R.get(p.id).star));controls.append(el('span','',t('readState')),state,star);const note=el('textarea');note.value=R.get(p.id).note;note.placeholder=t('notesPlaceholder');note.maxLength=50000;note.setAttribute('aria-label',t('notes'));note.oninput=()=>{status.textContent=t(R.set(p.id,{note:note.value})?'saved':'saveFailed');};box.append(controls,note,status,el('small','',t('notesHint')));return box;}
function renderMetadata(p){const box=el('details','metadata');box.append(el('summary','',t('versions')));const m=p.metadata||{},keys={matched:'metadataMatched',conflict:'metadataConflict',not_found:'metadataMissing',error:'metadataError'};box.append(el('p','',t(keys[m.status]||'metadataNotChecked')+' · '+t('metadataOnly')));if(m.checked_at)box.append(el('p','',t('checkedAt')+': '+m.checked_at.slice(0,10)));if(m.bibliography){const b=m.bibliography;box.append(el('p','',b.title),el('p','',[b.journal,b.date,...(b.authors||[]).map(a=>[a.given,a.family].filter(Boolean).join(' '))].filter(Boolean).join(' · ')));}for(const diff of m.differences||[])box.append(el('p','error',(lang==='en'?diff.en:diff.zh)||diff.en));if(safeURL(m.source_url))box.append(external(t('sourceLink'),m.source_url));box.append(el('p','',t('related')));if(!(m.relations||[]).length)box.append(el('p','',t(m.status==='matched'?'noRelations':'metadataNotChecked')));for(const r of m.relations||[])if(safeURL(r.url))box.append(el('p','').appendChild(external(r.type+' · '+(r.id||r.url),r.url)).parentNode);box.append(el('p','',t('updates')));if(!(m.updates||[]).length)box.append(el('p','',t(m.update_check==='completed'?'noUpdates':m.update_check==='unavailable'?'metadataError':'metadataNotChecked')));for(const u of m.updates||[])if(safeURL(u.url))box.append(el('p','').appendChild(external(u.type+' · '+u.doi,u.url)).parentNode);box.append(el('p','',t('reviewVersions')));for(const rev of revisions[p.id]||[])box.append(link('v'+rev.version+' · '+rev.at.slice(0,10)+'  ',paperHref(p.id,rev.version)));return box;}
function renderPaper(p,index,detail=false){const article=el('article','paper'),translation=lang==='en'?p.translations?.en:p,heading=translation?.heading||p.title,sections=translation?.sections||[];const title=el(detail?'h2':'h3','paper-heading');title.append(link(term(p.priority)+' | '+heading,paperHref(p.id,p.revision)));article.append(title,el('h4','',p.title));const meta=el('div','meta');meta.append(el('span','badge',term(p.priority)),el('span','',term(p.kind)),el('span','',p.journal),el('time','',p.date),el('span','',t(selected?'entryVersion':'version')+' '+(p.revision||1)));article.append(meta);const note=el('div','evidence-box'),abstract=p.evidence?.source_type==='abstract';note.append(el('strong','',t('source')+': '+t(abstract?'abstract':'historical')),el('p','',t('contentPending')));if(lang==='en')note.append(el('p','',t('translationNote')));article.append(note);const chips=el('div','tags');Object.entries(p.classification).forEach(([k,vs])=>vs.forEach(v=>{const b=button(term(v),()=>{if(detail){location.href=route({tag:k+':'+v});return;}const tag=k+':'+v;tags.has(tag)?tags.delete(tag):tags.add(tag);updateURL();render();},'tag');b.setAttribute('aria-pressed',String(tags.has(k+':'+v)));chips.append(b);}));article.append(chips,el('p','classification-note',t('classificationNote')));const list=el('ul','analysis-sections');sections.forEach((s,i)=>{const row=el('li','insight');row.append(el('strong','',s.label+': '));if(i<4)row.append(el('span','section-kind',t(i>=2?'proposal':abstract?'report':'legacyReport')));row.append(document.createTextNode(s.text));list.append(row);});article.append(list);const actions=exports([p]);if(safeURL(p.url))actions.prepend(external(t('readOriginal')+' ↗',p.url));if(!detail)actions.append(link(t('viewPaper'),paperHref(p.id,p.revision)));article.append(actions,renderReader(p),renderMetadata(p));if(detail){const issues=el('p','issue-links',t('issueLinks')+': ');for(const date of p.issues||[])issues.append(link(date,route({issue:date})));article.append(issues);}return article;}
function buildControls(){document.documentElement.lang=lang==='en'?'en':'zh-CN';document.querySelectorAll('[data-i18n]').forEach(n=>n.textContent=t(n.dataset.i18n));for(const l of ['zh','en']){$(l).classList.toggle('active',lang===l);$(l).setAttribute('aria-pressed',String(lang===l));}const nav=$('navigation');nav.replaceChildren();for(const v of ['library','topics','candidates','personal']){const a=link(t(v),route({view:v}));a.classList.toggle('active',view===v&&!selected);nav.append(a);}$('issues').replaceChildren(...data.issues.map(i=>{const a=link(i.date,route({issue:i.date}));a.classList.toggle('active',i.date===selected);return a;}));$('search').placeholder=t('search');$('search').setAttribute('aria-label',t('search'));$('search').value=query;$('priority').replaceChildren();option($('priority'),'',t('priority'));for(const v of ['全文精读','快速浏览','背景参考'])option($('priority'),v,term(v));$('priority').value=priority;$('priority').setAttribute('aria-label',t('priority'));$('reading').replaceChildren();option($('reading'),'',t('anyReading'));for(const v of ['todo','read','star'])option($('reading'),v,t(v==='star'?'favoritesOnly':v));$('reading').value=reading;$('reading').setAttribute('aria-label',t('readState'));$('filters').replaceChildren();for(const[k,c]of Object.entries(catalog.taxonomy)){const label=el('label','',term(c.label)),s=el('select');option(s,'',t('all'));for(const v of c.values)option(s,v,term(v));s.value=filters[k]||'';s.onchange=()=>{filters[k]=s.value;updateURL();render();};label.append(s);$('filters').append(label);}const counts={};for(const p of catalog.papers)for(const[k,vs]of Object.entries(p.classification))for(const v of vs)counts[k+':'+v]=(counts[k+':'+v]||0)+1;$('tagbar').replaceChildren(...Object.entries(counts).sort((a,b)=>b[1]-a[1]).map(([tag,n])=>{const b=button(term(tag.split(':')[1])+' '+n,()=>{tags.has(tag)?tags.delete(tag):tags.add(tag);updateURL();render();},'tag');b.setAttribute('aria-pressed',String(tags.has(tag)));return b;}));}
function backupTools(){const box=$('tools'),status=el('span');box.append(button(t('exportNotes'),()=>{download('plant-epigenomics-reading.json',JSON.stringify(R.backup(),null,2),'application/json');status.textContent=t('noteExported');}));const input=el('input');input.type='file';input.accept='.json,application/json';input.hidden=true;input.onchange=async()=>{try{const f=input.files[0];if(!f)return;if(f.size>10000000)throw Error('Large');const ok=R.restore(JSON.parse(await f.text()));render();$('tools').append(el('span','',t(ok?'imported':'saveFailed')));}catch{status.textContent=t('invalidBackup');}finally{input.value='';}};box.append(button(t('importNotes'),()=>input.click()),input,status,el('small','',t('importHint')));}
function render(){if(!data)return;buildControls();$('papers').replaceChildren();$('tools').replaceChildren();$('topic-content').replaceChildren();$('detail-nav').replaceChildren();$('result-count').textContent='';$('controls').hidden=Boolean(detailId)||view==='topics'&&!topicId;$('summary').textContent='';if(detailId){const original=catalog.papers.find(x=>x.id===detailId),version=Number(params.get('version'));let p=original;if(p&&version){const rev=(revisions[p.id]||[]).find(r=>r.version===version);if(rev)p={...p,...rev.content,revision:rev.version};}$('detail-nav').append(link('← '+t('back'),route()));$('edition-title').textContent=t('viewPaper');if(p)$('papers').append(renderPaper(p,0,true));else $('papers').append(el('p','empty',t('noResults')));backupTools();renderStatus();return;}
 $('edition-title').textContent=selected||t(view);const issue=data.issues.find(i=>i.date===selected);$('summary').textContent=issue?(lang==='en'?issue.summary_en:issue.summary):t(({library:'allDescription',topics:'topicIntro',candidates:'candidateIntro',personal:'personalIntro'})[view]||'allDescription');
 if(view==='topics'&&!topicId){const grid=el('div','topic-grid');for(const topic of topics){const x=topic[lang],card=el('section','topic-card');card.append(el('p','eyebrow',t('theme')),el('h3','',x.title),el('p','',x.intro),link(t('topicRead')+' →',route({view:'topics',topic:topic.id})));grid.append(card);}$('topic-content').append(grid);renderStatus();return;}
 if(topicId){const topic=topics.find(x=>x.id===topicId);if(topic){const x=topic[lang],box=el('section','topic-guide');$('edition-title').textContent=x.title;box.append(el('p','',x.intro));for(const[k,label]of [['leads','topicScope'],['methods','topicMethods'],['questions','topicQuestions'],['caution','topicCaution']]){box.append(el('h3','',t(label)));const value=x[k];if(Array.isArray(value)){const list=el('ul');value.forEach(s=>list.append(el('li','',s)));box.append(list);}else box.append(el('p','',value));}$('topic-content').append(box);}}
 if(view==='candidates'){document.querySelector('.filter-panel').hidden=true;$('tagbar').hidden=true;document.querySelector('.tag-heading').hidden=true;$('priority').hidden=true;$('reading').hidden=true;const rows=(pool.records||[]).filter(r=>!query||(r.title+' '+(r.abstract||'')).toLowerCase().includes(query.toLowerCase()));$('result-count').textContent=rows.length+' '+t('count');$('tools').append(el('span','',t('poolDate')+': '+(pool.updated_at||t('unknown'))));for(const search of pool.searches||[])$('tools').append(el('small','',t(search.lane+'Lane')+': '+(search.ok?(search.count||0):t('partial'))));for(const r of rows){const card=el('article','candidate');card.append(el('h3','',r.title),el('p','',[r.journal,r.date,t(r.recommended?'candidateSelected':'candidatePending')].filter(Boolean).join(' · ')));if(safeURL(r.url))card.append(external(t('readOriginal')+' ↗',r.url));$('papers').append(card);}if(!rows.length)$('papers').append(el('p','empty',t(pool.records?.length?'noResults':'candidateEmpty')));renderStatus();return;}
 document.querySelector('.filter-panel').hidden=false;$('tagbar').hidden=false;document.querySelector('.tag-heading').hidden=false;$('priority').hidden=false;$('reading').hidden=false;const papers=filteredPapers();$('result-count').textContent=papers.length+' / '+catalog.papers.length+' '+t('count');$('tools').append(exports(papers),el('small','',t('citationCaution')));if(view==='personal')backupTools();$('papers').replaceChildren(...papers.map((p,i)=>renderPaper(p,i)));if(!papers.length)$('papers').append(el('p','empty',t(view==='personal'?'personalEmpty':'noResults')));renderStatus();}
async function json(url){const response=await fetch(url,{cache:'no-store'});if(!response.ok)throw Error('HTTP '+response.status);return response.json();}
function renderStatus(){const snapshot=statusSnapshot,search=snapshot.last_search;$('search-stats').textContent=search?[t('lastSearch'),search.at,search.retrieved+' '+t('retrieved'),search.candidates+' '+t('candidateCount'),search.recommended+' '+t('recommended'),search.partial?t('partial'):''].filter(Boolean).join(' · '):t('noSearch');const runs=liveRuns||snapshot.runs;if(!runs){$('run-status').textContent=t('statusUnavailable');return;}const weekly=runs.weekly||[],publish=runs.publish||[],all=[...weekly,...publish].sort((a,b)=>b.created_at.localeCompare(a.created_at)),success=all.filter(r=>r.conclusion==='success').sort((a,b)=>b.updated_at.localeCompare(a.updated_at))[0],grid=el('div','status-grid');for(const[key,r]of [['lastWeekly',weekly[0]],['lastTask',all[0]],['lastPublish',success]]){const cell=el('div');cell.append(el('span','',t(key)),el('strong','',r?(key==='lastPublish'?r.updated_at.replace('T',' ').replace('Z',' UTC'):t(r.status!=='completed'?'running':r.conclusion||'unknown')):t('unknown')));if(r&&safeURL(r.html_url))cell.append(external(t('runRecords')+' ↗',r.html_url));grid.append(cell);}$('run-status').replaceChildren(grid);$('status-note').textContent=(liveRuns?'':t('snapshot')+' ')+t('statusExplanation');}
for(const l of ['zh','en'])$(l).onclick=()=>{lang=l;try{localStorage.setItem('digest-language',l);}catch{}updateURL();render();};$('search').oninput=e=>{query=e.target.value;updateURL();render();};$('priority').onchange=e=>{priority=e.target.value;updateURL();render();};$('reading').onchange=e=>{reading=e.target.value;updateURL();render();};$('clear').onclick=()=>{query='';priority='';reading='';tags.clear();for(const k of Object.keys(filters))filters[k]='';updateURL();render();};window.addEventListener('popstate',()=>location.reload());
Promise.all(['digest','catalog','topics','candidates','revisions'].map(name=>json(base+name+'.json'))).then(([d,c,tp,cp,rv])=>{data=d;catalog=c;topics=tp;pool=cp;revisions=rv;data.issues.sort((a,b)=>b.date.localeCompare(a.date));if(!['library','topics','personal','candidates'].includes(view))view='library';if(selected&&!data.issues.some(i=>i.date===selected))selected='';for(const[k,c]of Object.entries(catalog.taxonomy))filters[k]=c.values.includes(params.get(k))?params.get(k):'';render();}).catch(()=>{$('edition-title').textContent=t('loadError');});
(async()=>{try{statusSnapshot=await json(base+'status.json');}catch{}try{const root='https://api.github.com/repos/qliugithub/plant-epigenomics-weekly-digest/actions/workflows/';const[a,b]=await Promise.all([json(root+'weekly.yml/runs?per_page=10'),json(root+'publish.yml/runs?per_page=10')]);liveRuns={weekly:a.workflow_runs,publish:b.workflow_runs};}catch{}if(data)renderStatus();})();
